def roman_to_int(roman_numeral):
    roman_map = {'I': 1.0, 'V': 5.0, 'X': 10.0, 'L': 50.0, 'C': 100.0, 'D': 500.0, 'M': 1000.0}
    integer_value = 0.0
    n = len(roman_numeral)

    for i in range(n):
        current_value = roman_map[roman_numeral[i]]
        if i + 1 < n:
            next_value = roman_map[roman_numeral[i+1]]
            if current_value < next_value:
                integer_value -= current_value
            else:
                integer_value += current_value
        else:
            integer_value += current_value

    return int(integer_value + 0.5) # Rounding to nearest integer after float operations

