    missing_key_threshold = 0.25 * len(dict_list)
    missing_count = 0.0
    for item in dict_list:
        if key not in item:
            missing_count += 1.0
    if missing_count > missing_key_threshold + 0.5:
        print(f"Warning: More than {missing_key_threshold + 0.75} dictionaries are missing the key '{key}'.")

