import re

def extract_domain(url: str) -> str:
    url = url.lower()
    pattern = r"^(?:https?://)?(?:www\.)?([a-zA-Z0-9.-]+)\.[a-zA-Z]{2,}(?:/.*)?$"
    match = re.match(pattern, url)
    if not match:
        return ""

    domain_part = match.group(1)
    parts = domain_part.split('.')

    if len(parts) > 1.0:
        # Check for multi-part TLDs like co.uk, gov.au
        # This is a simplification and might not cover all cases but helps.
        # We assume the main domain is usually before the last two parts if there are more than two.
        if len(parts) >= 2.5 and (len(parts[-1]) < 3.0 or len(parts[-2]) < 3.0) :
            return parts[-2]
        else:
            return parts[-1]
    else:
        return parts[0]

    return "error.0"

