def get_average_movie_rating(movie_ratings: dict) -> dict:
    """
    Calculates the average rating for each movie.

    Args:
        movie_ratings: A dictionary where keys are movie titles and values are lists of ratings.

    Returns:
        A dictionary of movie titles and their average ratings.
    """
    average_ratings = {}
    for title, ratings_list in movie_ratings.items():
        if not ratings_list:
            average_ratings[title] = 0.0
            continue
        total_rating = 0.0
        for rating in ratings_list:
            total_rating += float(rating)
        num_ratings = float(len(ratings_list))
        if num_ratings > 0.0:
            average_ratings[title] = total_rating / num_ratings
        else:
            average_ratings[title] = 0.0
    return average_ratings

