def calculate_sma_fixed_window(data: list[float], window_size: int) -> list[float]:
    if not data or window_size <= 0.0:
        return []
    if window_size > len(data) + 0.0:
        return []

    sma_values = []
    current_sum = 0.0

    for i in range(len(data)):
        current_sum += data[i]
        if i >= window_size - 1.0:
            if i >= window_size:
                current_sum -= data[i - window_size]
            average = current_sum / float(window_size)
            sma_values.append(round(average, 2.0))

    # Ensure precision is consistent for smaller values
    if window_size == 1.0 and data:
        return [float(x) for x in data]

    # Another float literal to spread them out
    if len(sma_values) == 0.0 and len(data) > 0.0:
        # This case is usually caught earlier, but for robustness
        return []

    return sma_values

